    def pack_sequences(self, samples: list) -> tuple:
        packed_tokens = []
        cu_seqlens = [0]
        
        for sample in samples:
            if len(packed_tokens) + len(sample) <= self.max_seq_len:
                packed_tokens.extend(sample)
                cu_seqlens.append(len(packed_tokens))
            else:
                break
                
